/* Root stop cannot reinterpret retained BASE; acknowledged StopSounds cancels it before a new event. */
#include "mixed_native.hpp"
int main()
{
 MixedNative f;f.advance();size_t n=0;assert(fvm_swf_stream_output_pump_mix_until(&f.audio.stream_output,f.audio.composition,1,&n)==FVM_OK && n==2);f.fifo.fail_write=1;assert(fvm_test_mixed_refill(&f.audio)==FVM_ERROR);FVM_SWFSoundMixQueuePending pending;pending.struct_size=sizeof(pending);assert(fvm_swf_sound_mix_queue_pending(f.audio.composition,&pending)==FVM_OK && pending.origin==FVM_SWF_SOUND_MIX_QUEUE_PENDING_BASE);FVM_SWFStreamConverter cursor=f.audio.stream_segments[0].converter;FVM_Value out;assert(fvm_object_call(f.context,f.clip,"stop",0,0,&out)==FVM_OK && fvm_desktop_audio_timeline(f.context,f.clip,&f.audio)==FVM_OK);f.fifo.fail_write=0;size_t calls=f.fifo.calls;f.refill();assert(f.fifo.calls==calls && !memcmp(&cursor,&f.audio.stream_segments[0].converter,sizeof(cursor)));int has=0;assert(fvm_desktop_audio_stream_pending(&f.audio,&has)==FVM_OK && has);f.fifo.count=0;assert(fvm_desktop_audio_stream_pending(&f.audio,&has)==FVM_OK && !has);assert(fvm_gc_collect(f.context,0)==FVM_OK);f.fifo.fail_clear=1;assert(fvm_audio_stop_all(f.context)==FVM_ERROR && !f.audio.stops);assert(fvm_swf_sound_mix_queue_pending(f.audio.composition,&pending)==FVM_OK && pending.frames==2);f.fifo.fail_clear=0;assert(fvm_audio_stop_all(f.context)==FVM_OK && f.audio.stops==1 && !active(f.audio.mixer));FVM_Value frame;fvm_value_number(&frame,2);assert(fvm_object_call(f.context,f.clip,"gotoAndStop",1,&frame,&out)==FVM_OK && fvm_desktop_audio_timeline(f.context,f.clip,&f.audio)==FVM_OK);f.advance();assert(f.audio.stream_movie_paused && f.audio.events==2);for(unsigned i=0;i<8;++i){f.fifo.count=0;f.refill();}assert(f.fifo.total==12);for(unsigned i=0;i<2;++i)assert(f.fifo.samples[i*2]==2100);for(unsigned i=2;i<12;++i)assert(f.fifo.samples[i*2]==(i<11?2000:0));return 0;
}
